  /**
   * How long the sampled series now spans, hours.
   */
  seriesSpanHours: number
  /**
   * When sampling of the queues began, RFC 3339 UTC. Together with `seriesSpanHours`
   * it says whether a "versus 7-day / 30-day average" comparison can render at all.
   */
  seriesStartTime?: string | null
  /**
   * Validator counts by status, with their trailing averages and snapshot weights.
   */
  status: ConsensusCurrentStatus
  /**
   * Total effective balance of the active set, gwei, decimal string.
   * `queues.activeSet.gwei` is the ACTUAL balance of the same set, which the churn
   * limits in `queues.churn` are computed from.
   */
