/**
 * A token's USD price for one hour.
 */
export interface TokenPrice {
  /**
   * Hours between `observedHour` and `hour`.
   */
  ageHours?: number | null
  /**
   * Chain id. `1` is Ethereum mainnet.
   */
  chainId: number
  /**
   * The DEX side of the hour; absent when there is none.
   */
  dex?: TokenPriceDex | null
  /**
   * How far the oracle and DEX prices disagree, percent, when both exist. A number, not a
   * verdict.
   */
  divergencePct?: number | null
  /**
   * The hour the price is for, Unix seconds (its start).
   */
  hour: number
  /**
   * The largest USD value (amount × `priceUsd`) this price may vouch for. Absent means no
   * bound. An amount worth more at this price is not valued by it.
   */
  maxTrustedValueUsd?: number | null
  /**
   * The hour it was observed in, Unix seconds — earlier than `hour` when carried.
   */
  observedHour?: number | null
  /**
   * The oracle side of the hour; absent when there is none.
   */
  oracle?: TokenPriceOracle | null
  /**
   * What the price is: `chainlink_oracle`, `aave_oracle`, `dex_observed`, `stable_peg`, or
   * one of them carried over from an earlier hour (`chainlink_carried`,
   * `aave_oracle_carried`, `dex_carried`).
   */
  priceSource: string
  /**
   * The USD price.
   */
  priceUsd: number
  /**
   * The token, lowercase and `0x`-prefixed.
   */
  token: string
}

